package com.metaverse.coin.strategy.core.arbitrage.multi;
import com.fasterxml.jackson.databind.JsonNode; import java.math.BigDecimal; import java.net.URI; import java.time.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class HtxFundingRateGateway extends ReadOnlyFundingRateGateway implements PerpetualExchangeGateway {
 public Exchange exchange(){return Exchange.HTX;}
 protected URI fundingUri(String s){return URI.create("https://api.hbdm.com/linear-swap-api/v1/swap_funding_rate?contract_code="+s.replace("USDT","-USDT"));}
 protected URI markPriceUri(String s){return URI.create("https://api.hbdm.com/linear-swap-ex/market/detail/merged?contract_code="+s.replace("USDT","-USDT"));}
 protected BigDecimal fundingRate(JsonNode n){return n.path("data").path("funding_rate").decimalValue();}
 protected BigDecimal markPrice(JsonNode n){return n.path("tick").path("close").decimalValue();}
 private String contract(String s){return s.substring(0,s.length()-4)+"-USDT";}
 public List<String> supportedUsdtPerpetualSymbols(){List<String>r=new ArrayList<>();for(JsonNode n:getJson(URI.create("https://api.hbdm.com/linear-swap-api/v1/swap_contract_info")).path("data"))if(n.path("contract_status").asInt()==1&&"USDT".equals(n.path("settlement_asset").asText("USDT")))r.add(n.path("symbol").asText()+"USDT");return r;}
 public List<PerpetualContract> listContracts(){Map<String,BigDecimal>prices=new HashMap<>();JsonNode market=getJson(URI.create("https://api.hbdm.com/linear-swap-ex/market/detail/batch_merged"));for(JsonNode t:market.path("ticks"))prices.put(t.path("contract_code").asText(),t.path("close").decimalValue());List<PerpetualContract>r=new ArrayList<>();for(JsonNode n:getJson(URI.create("https://api.hbdm.com/linear-swap-api/v1/swap_contract_info")).path("data")){if(n.path("contract_status").asInt()!=1||!"USDT".equals(n.path("settlement_asset").asText("USDT")))continue;String exchangeSymbol=n.path("contract_code").asText();BigDecimal tick=n.path("price_tick").decimalValue();BigDecimal contractSize=n.path("contract_size").decimalValue();BigDecimal minimum=contractSize.multiply(prices.getOrDefault(exchangeSymbol,BigDecimal.ZERO));if(tick.signum()>0&&minimum.signum()>0)r.add(new PerpetualContract(n.path("symbol").asText()+"USDT",exchangeSymbol,0,scale(tick),minimum));}return r;}
 public NormalizedFundingRateSnapshot fundingRate(String s){String c=contract(s);JsonNode f=getJson(URI.create("https://api.hbdm.com/linear-swap-api/v1/swap_funding_rate?contract_code="+c)).path("data");JsonNode m=getJson(URI.create("https://api.hbdm.com/linear-swap-ex/market/detail/merged?contract_code="+c)).path("tick");JsonNode i=getJson(URI.create("https://api.hbdm.com/linear-swap-api/v1/swap_index?contract_code="+c)).path("data").path(0);long next=f.path("next_funding_time").asLong(f.path("funding_time").asLong());return new NormalizedFundingRateSnapshot(exchange(),s,f.path("funding_rate").decimalValue(),8,Instant.ofEpochMilli(next),m.path("close").decimalValue(),i.path("index_price").decimalValue(),Instant.now());}
 public NormalizedOrderBookSnapshot orderBook(String s,int depth){JsonNode t=getJson(URI.create("https://api.hbdm.com/linear-swap-ex/market/depth?contract_code="+contract(s)+"&type=step0")).path("tick");return new NormalizedOrderBookSnapshot(exchange(),s,price(t,"bids"),price(t,"asks"),sum(t.path("bids"),depth),sum(t.path("asks"),depth),Instant.now());}
 private BigDecimal price(JsonNode n,String x){return new BigDecimal(n.path(x).path(0).path(0).asText());}private BigDecimal sum(JsonNode a,int d){BigDecimal x=BigDecimal.ZERO;int i=0;for(JsonNode l:a){if(i++>=d)break;x=x.add(new BigDecimal(l.path(0).asText()).multiply(new BigDecimal(l.path(1).asText())));}return x;}
 private int scale(BigDecimal step){return Math.max(0,step.stripTrailingZeros().scale());}
}
